import type { WisdomArticle } from "./types";

/** Articles sourced verbatim from temp-content/p2.txt (link-scrubbed, headings normalized) */
export const p2Articles: WisdomArticle[] = [
  {
    id: "origins-of-jyotish",
    section: "introduction",
    title: { en: `Jyotish – Origins of Vedic Astrology`, ja: `Jyotish – Origins of Vedic Astrology` },
    related: ["origins-intro","jyotish-and-karma","paradigm-shift"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Jyotish – Origins of Vedic Astrology`, ja: `Jyotish – Origins of Vedic Astrology` } },
      { type: "paragraph", text: { en: `Summary: This article explores the origins of Vedic Astrology (Jyotish) and the process of Vedic cognition. It identifies the great Vedic Seer Maharishi Parashara as the ‘father of Jyotish Astrology’ and discusses his classical Jyotish text, the Brihat Parasara Hora Shastra.`, ja: `Summary: This article explores the origins of Vedic Astrology (Jyotish) and the process of Vedic cognition. It identifies the great Vedic Seer Maharishi Parashara as the ‘father of Jyotish Astrology’ and discusses his classical Jyotish text, the Brihat Parasara Hora Shastra.` } },
      { type: "heading", level: 3, text: { en: `Origins of Vedic Astrology and the Process of Vedic Cognition`, ja: `Origins of Vedic Astrology and the Process of Vedic Cognition` } },
      { type: "paragraph", text: { en: `Ask a Western Astrologer about the origins of astrology and they will usually provide a chronological account describing how the subject passed from one culture to another, moving between countries and civilizations over time. Western modes of thought are comfortable with this approach because it aligns with our sense of history. We enjoy organising the past through names, dates, timelines, and geographical locations.`, ja: `Ask a Western Astrologer about the origins of astrology and they will usually provide a chronological account describing how the subject passed from one culture to another, moving between countries and civilizations over time. Western modes of thought are comfortable with this approach because it aligns with our sense of history. We enjoy organising the past through names, dates, timelines, and geographical locations.` } },
      { type: "paragraph", text: { en: `Ask a Jyotish Astrologer the same question and the answer is likely to be that it “came from God” [1]. This is a crucial point and highlights a fundamental distinction between Jyotish and Western Astrology. According to Vedic tradition, the knowledge of Jyotish Astrology, just like the knowledge of maintaining perfect health through Ayurveda and the vast body of Vedic Science as a whole, was not invented but rather revealed or cognized.`, ja: `Ask a Jyotish Astrologer the same question and the answer is likely to be that it “came from God” [1]. This is a crucial point and highlights a fundamental distinction between Jyotish and Western Astrology. According to Vedic tradition, the knowledge of Jyotish Astrology, just like the knowledge of maintaining perfect health through Ayurveda and the vast body of Vedic Science as a whole, was not invented but rather revealed or cognized.` } },
      { type: "paragraph", text: { en: `Jyotish was neither discovered nor created by human beings, nor was it gradually developed through experimentation over centuries.`, ja: `Jyotish was neither discovered nor created by human beings, nor was it gradually developed through experimentation over centuries.` } },
      { type: "paragraph", text: { en: `There are few clear equivalents within Western thought to explain the process of Vedic cognition. Perhaps the closest comparison would be moments of extraordinary artistic inspiration, creative genius, or scientific insight, where the complete understanding of a great work, invention, or theorem seems to appear in the mind instantly.`, ja: `There are few clear equivalents within Western thought to explain the process of Vedic cognition. Perhaps the closest comparison would be moments of extraordinary artistic inspiration, creative genius, or scientific insight, where the complete understanding of a great work, invention, or theorem seems to appear in the mind instantly.` } },
      { type: "heading", level: 3, text: { en: `Modern ‘Download’ Analogy to Vedic Cognition Process`, ja: `Modern ‘Download’ Analogy to Vedic Cognition Process` } },
      { type: "paragraph", text: { en: `All of the great works of Vedic Science are said to have originated through revealed knowledge or cognition within the consciousness of highly evolved sages, seers, and Rishis of ancient times. These individuals devoted entire lifetimes to the practice of Yoga and meditation, enabling them to access higher states of awareness. Their level of consciousness was far beyond what most people experience in everyday life.`, ja: `All of the great works of Vedic Science are said to have originated through revealed knowledge or cognition within the consciousness of highly evolved sages, seers, and Rishis of ancient times. These individuals devoted entire lifetimes to the practice of Yoga and meditation, enabling them to access higher states of awareness. Their level of consciousness was far beyond what most people experience in everyday life.` } },
      { type: "paragraph", text: { en: `A useful modern analogy is the Internet. Imagine connecting a personal computer to a remote server—or even to “The Cloud”—and downloading all the information required directly into the machine. Naturally, we must know how to operate the computer correctly and possess the necessary password—perhaps comparable to using the correct Sanskrit mantras—to gain access to the information stored remotely. This analogy reflects the Vedic Model of Reality, in which the universe and all living beings are viewed as parts of an interconnected whole.`, ja: `A useful modern analogy is the Internet. Imagine connecting a personal computer to a remote server—or even to “The Cloud”—and downloading all the information required directly into the machine. Naturally, we must know how to operate the computer correctly and possess the necessary password—perhaps comparable to using the correct Sanskrit mantras—to gain access to the information stored remotely. This analogy reflects the Vedic Model of Reality, in which the universe and all living beings are viewed as parts of an interconnected whole.` } },
      { type: "paragraph", text: { en: `If we continue with this analogy, it becomes clear that the information stored on a server exists whether or not our computer, tablet, or phone can access it. The same principle applies to the knowledge of Vedic Astrology. The information within the “Cosmic Computer” is always present, waiting to be accessed. During certain ages, direct access to this knowledge may be available to a small number of enlightened individuals.`, ja: `If we continue with this analogy, it becomes clear that the information stored on a server exists whether or not our computer, tablet, or phone can access it. The same principle applies to the knowledge of Vedic Astrology. The information within the “Cosmic Computer” is always present, waiting to be accessed. During certain ages, direct access to this knowledge may be available to a small number of enlightened individuals.` } },
      { type: "paragraph", text: { en: `In the current Dark Age of Kali Yuga [2], direct cognition is considered unavailable. As a result, we rely upon the cognized wisdom passed down by enlightened sages from previous ages.`, ja: `In the current Dark Age of Kali Yuga [2], direct cognition is considered unavailable. As a result, we rely upon the cognized wisdom passed down by enlightened sages from previous ages.` } },
      { type: "heading", level: 3, text: { en: `Maharishi Parashara – ‘Father’ of Vedic Astrology`, ja: `Maharishi Parashara – ‘Father’ of Vedic Astrology` } },
      { type: "paragraph", text: { en: `The Vedic Sage, or Seer, most widely regarded as the “father of Jyotish Astrology” is Maharishi Parashara (Maha meaning “great” and Rishi meaning “seer”) [3]. His Sanskrit work, the Brihat Parasara Hora Shastra [4], remains one of the most important and influential texts in Vedic Astrology.`, ja: `The Vedic Sage, or Seer, most widely regarded as the “father of Jyotish Astrology” is Maharishi Parashara (Maha meaning “great” and Rishi meaning “seer”) [3]. His Sanskrit work, the Brihat Parasara Hora Shastra [4], remains one of the most important and influential texts in Vedic Astrology.` } },
      { type: "paragraph", text: { en: `From the Vedic perspective, exactly when or where Parashara lived is of secondary importance. Even if his teachings had been lost over the course of time, it would not fundamentally matter because the knowledge was never considered to be personally his. The wisdom itself existed independently and was simply cognized through him. Future Rishis born in other ages could once again re-cognize the complete body of Jyotish Shastra and make it available for the benefit of humanity.`, ja: `From the Vedic perspective, exactly when or where Parashara lived is of secondary importance. Even if his teachings had been lost over the course of time, it would not fundamentally matter because the knowledge was never considered to be personally his. The wisdom itself existed independently and was simply cognized through him. Future Rishis born in other ages could once again re-cognize the complete body of Jyotish Shastra and make it available for the benefit of humanity.` } },
      { type: "heading", level: 3, text: { en: `Footnotes`, ja: `Footnotes` } },
      { type: "paragraph", text: { en: `[1] The Vedic concept of God differs significantly from the idea of a distant, judgemental deity often associated with the Abrahamic traditions. In the Vedic understanding, the all-pervading “GOD” may be viewed as a three-letter acronym representing fundamental principles of nature: G – Generator (personified as Brahma), O – Operator (personified as Vishnu), and D – Destroyer (personified as Maheshwara or Shiva). This divine reality is not something separate from us; rather, we exist within it, just as a fish exists within the ocean. Some describe it as the “field of creative intelligence.” There are also many interesting parallels between this Vedic Model of Reality and modern scientific models.`, ja: `[1] The Vedic concept of God differs significantly from the idea of a distant, judgemental deity often associated with the Abrahamic traditions. In the Vedic understanding, the all-pervading “GOD” may be viewed as a three-letter acronym representing fundamental principles of nature: G – Generator (personified as Brahma), O – Operator (personified as Vishnu), and D – Destroyer (personified as Maheshwara or Shiva). This divine reality is not something separate from us; rather, we exist within it, just as a fish exists within the ocean. Some describe it as the “field of creative intelligence.” There are also many interesting parallels between this Vedic Model of Reality and modern scientific models.` } },
      { type: "paragraph", text: { en: `[2] Vedic literature describes four major ages, or great cycles of time, each characterised by distinct qualities. Most, though not all, scholars maintain that humanity is currently living in the age of Kali Yuga. There is ongoing debate regarding exactly when this age began—many place its commencement around 3102 BCE, following the departure of Krishna from His earthly incarnation—and how long it will continue. Some estimates suggest approximately another 17,000 years, while others propose a much longer duration. Certain scholars also suggest the existence of smaller cycles operating within the larger Yuga framework.`, ja: `[2] Vedic literature describes four major ages, or great cycles of time, each characterised by distinct qualities. Most, though not all, scholars maintain that humanity is currently living in the age of Kali Yuga. There is ongoing debate regarding exactly when this age began—many place its commencement around 3102 BCE, following the departure of Krishna from His earthly incarnation—and how long it will continue. Some estimates suggest approximately another 17,000 years, while others propose a much longer duration. Certain scholars also suggest the existence of smaller cycles operating within the larger Yuga framework.` } },
      { type: "paragraph", text: { en: `[3] Parashara is credited with cognizing the rules, principles, and systematic framework that form the basis of Jyotish.`, ja: `[3] Parashara is credited with cognizing the rules, principles, and systematic framework that form the basis of Jyotish.` } },
      { type: "paragraph", text: { en: `[4] Scholars continue to debate which chapters of the currently available printed editions of the Brihat Parasara Hora Shastra can be directly attributed to Parashara and which may originate from the Sage Jaimini. Although the two systems sometimes appear to differ, it is generally accepted that Parashara’s methods are particularly suited to the present age of Kali Yuga, while Jaimini’s teachings may have been intended for a different age.`, ja: `[4] Scholars continue to debate which chapters of the currently available printed editions of the Brihat Parasara Hora Shastra can be directly attributed to Parashara and which may originate from the Sage Jaimini. Although the two systems sometimes appear to differ, it is generally accepted that Parashara’s methods are particularly suited to the present age of Kali Yuga, while Jaimini’s teachings may have been intended for a different age.` } },
    ],
  },
  {
    id: "jyotish-and-karma",
    section: "introduction",
    title: { en: `Jyotish and Karma`, ja: `Jyotish and Karma` },
    related: ["three-types-karma","predictive-capabilities","planetary-antidotes"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Jyotish and Karma`, ja: `Jyotish and Karma` } },
      { type: "paragraph", text: { en: `Summary: This article explores the principles of karma and reincarnation within the framework of Jyotish Astrology. It discusses the various categories of karma, explains how returning karmas can be identified, and describes how Vedic Astrology's remedial measures may help modify their effects.`, ja: `Summary: This article explores the principles of karma and reincarnation within the framework of Jyotish Astrology. It discusses the various categories of karma, explains how returning karmas can be identified, and describes how Vedic Astrology's remedial measures may help modify their effects.` } },
      { type: "heading", level: 3, text: { en: `Vedic Astrology, Karma and Reincarnation`, ja: `Vedic Astrology, Karma and Reincarnation` } },
      { type: "paragraph", text: { en: `In the West, the words kama and karma are often confused and sometimes mispronounced. Kama refers to desire, and many people are familiar with the Kama Sutra. Karma, on the other hand, literally means action. Since actions are constantly taking place, karma is continually being generated throughout the world.`, ja: `In the West, the words kama and karma are often confused and sometimes mispronounced. Kama refers to desire, and many people are familiar with the Kama Sutra. Karma, on the other hand, literally means action. Since actions are constantly taking place, karma is continually being generated throughout the world.` } },
      { type: "paragraph", text: { en: `The concept of karma carries many subtle meanings and layers of interpretation. On an individual level, karma is generally understood as the returning consequences of our past actions—summed up by the phrase, "as you sow, so shall you reap." Within the Vedic tradition, karma can extend across multiple incarnations. Karma is also closely connected with the concept of samskara (or sanskara)—the deep-rooted impressions and latent desires within the mind that motivate us to perform particular actions [1].`, ja: `The concept of karma carries many subtle meanings and layers of interpretation. On an individual level, karma is generally understood as the returning consequences of our past actions—summed up by the phrase, "as you sow, so shall you reap." Within the Vedic tradition, karma can extend across multiple incarnations. Karma is also closely connected with the concept of samskara (or sanskara)—the deep-rooted impressions and latent desires within the mind that motivate us to perform particular actions [1].` } },
      { type: "paragraph", text: { en: `According to Vedic Astrology, the soul (for want of a better term in the English language) does not take birth randomly. Vedic Masters teach that it incarnates into a human body—primarily—with specific physical traits determined by previous karmas. The family into which one is born, its social standing, and even the country of birth are likewise influenced by past karmic actions.`, ja: `According to Vedic Astrology, the soul (for want of a better term in the English language) does not take birth randomly. Vedic Masters teach that it incarnates into a human body—primarily—with specific physical traits determined by previous karmas. The family into which one is born, its social standing, and even the country of birth are likewise influenced by past karmic actions.` } },
      { type: "paragraph", text: { en: `Vedic Astrology further teaches that we are not victims of our birth chart or the planetary combinations contained within it. The planets cannot be blamed for our present circumstances or challenges. Whatever we are experiencing today, whether perceived as favourable or unfavourable, is simply the manifestation of returning karmas. The planets indicate these karmas, but they do not create them.`, ja: `Vedic Astrology further teaches that we are not victims of our birth chart or the planetary combinations contained within it. The planets cannot be blamed for our present circumstances or challenges. Whatever we are experiencing today, whether perceived as favourable or unfavourable, is simply the manifestation of returning karmas. The planets indicate these karmas, but they do not create them.` } },
      { type: "paragraph", text: { en: `In Jyotish, the planets are often described as the "Cosmic Postman." During this lifetime, they deliver some of the consequences of actions carried over from previous incarnations. We tend to label these karmas as "positive" when they bring growth, happiness, or success, and "negative" when they result in obstacles or difficulties [2]. Yet these labels are largely subjective. From a higher level of consciousness, the distinction between positive and negative karma disappears—things simply are as they are.`, ja: `In Jyotish, the planets are often described as the "Cosmic Postman." During this lifetime, they deliver some of the consequences of actions carried over from previous incarnations. We tend to label these karmas as "positive" when they bring growth, happiness, or success, and "negative" when they result in obstacles or difficulties [2]. Yet these labels are largely subjective. From a higher level of consciousness, the distinction between positive and negative karma disappears—things simply are as they are.` } },
      { type: "paragraph", text: { en: `A self-realized Vedic Master was once asked about free will and destiny. He replied that life consists of a combination of both. As an example, he explained that our height is largely predetermined, whereas our weight is influenced by our choices and actions. The audience immediately understood the point and laughed.`, ja: `A self-realized Vedic Master was once asked about free will and destiny. He replied that life consists of a combination of both. As an example, he explained that our height is largely predetermined, whereas our weight is influenced by our choices and actions. The audience immediately understood the point and laughed.` } },
      { type: "paragraph", text: { en: `In everyday life, many of our actions are karmically neutral. Following a reasonably vegetarian lifestyle is often said to support this balance.`, ja: `In everyday life, many of our actions are karmically neutral. Following a reasonably vegetarian lifestyle is often said to support this balance.` } },
      { type: "paragraph", text: { en: `Not only do our actions matter, but so do the intentions behind them. Through regular meditation and spiritual practices, our intentions become more aligned with evolution and natural growth, rather than being driven solely by impressions and tendencies carried over from previous lifetimes.`, ja: `Not only do our actions matter, but so do the intentions behind them. Through regular meditation and spiritual practices, our intentions become more aligned with evolution and natural growth, rather than being driven solely by impressions and tendencies carried over from previous lifetimes.` } },
      { type: "heading", level: 3, text: { en: `Prediction and ‘Prevention’ in Jyotish`, ja: `Prediction and ‘Prevention’ in Jyotish` } },
      { type: "paragraph", text: { en: `Jyotish enables us to both identify and redirect returning karmas. In this sense, it can truly be viewed as the ultimate Karmic Engineering System.`, ja: `Jyotish enables us to both identify and redirect returning karmas. In this sense, it can truly be viewed as the ultimate Karmic Engineering System.` } },
      { type: "heading", level: 3, text: { en: `1. Detecting Returning Karmas in Vedic Astrology`, ja: `1. Detecting Returning Karmas in Vedic Astrology` } },
      { type: "paragraph", text: { en: `The major karmic influences and significant events likely to arise during an individual's current incarnation can be predicted through Jyotish. This involves interpreting the "code" contained within the planetary arrangements present at the moment of birth. Just as DNA contains the information that shapes human physiology, the planetary configuration at birth contains the code that reflects returning karmas [3].`, ja: `The major karmic influences and significant events likely to arise during an individual's current incarnation can be predicted through Jyotish. This involves interpreting the "code" contained within the planetary arrangements present at the moment of birth. Just as DNA contains the information that shapes human physiology, the planetary configuration at birth contains the code that reflects returning karmas [3].` } },
      { type: "paragraph", text: { en: `Predictions can be made across all major areas of life, including Artha, Dharma, Kama, and Moksha.`, ja: `Predictions can be made across all major areas of life, including Artha, Dharma, Kama, and Moksha.` } },
      { type: "paragraph", text: { en: `Artha encompasses wealth in its broadest sense—financial prosperity, children, knowledge, food, health, and other forms of abundance.`, ja: `Artha encompasses wealth in its broadest sense—financial prosperity, children, knowledge, food, health, and other forms of abundance.` } },
      { type: "paragraph", text: { en: `Dharma relates to duty, character, righteous action, and activities that support evolution and natural law, including one's career path and life purpose.`, ja: `Dharma relates to duty, character, righteous action, and activities that support evolution and natural law, including one's career path and life purpose.` } },
      { type: "paragraph", text: { en: `Kama refers to desire and therefore includes relationships, pleasures of the senses, aspirations, and worldly enjoyments.`, ja: `Kama refers to desire and therefore includes relationships, pleasures of the senses, aspirations, and worldly enjoyments.` } },
      { type: "paragraph", text: { en: `Moksha concerns spiritual development, personal growth, and the journey toward Self-realization.`, ja: `Moksha concerns spiritual development, personal growth, and the journey toward Self-realization.` } },
      { type: "paragraph", text: { en: `Jyotish can also indicate when these karmic influences are likely to manifest. This is achieved through the unique Maha Dasa system of Vedic Astrology [4], which is based on the Moon's position in the Nakshatras (constellations) at the time of birth.`, ja: `Jyotish can also indicate when these karmic influences are likely to manifest. This is achieved through the unique Maha Dasa system of Vedic Astrology [4], which is based on the Moon's position in the Nakshatras (constellations) at the time of birth.` } },
      { type: "heading", level: 3, text: { en: `2. Deflecting Returning Karmas in Vedic Astrology`, ja: `2. Deflecting Returning Karmas in Vedic Astrology` } },
      { type: "paragraph", text: { en: `The Vedic tradition promotes a life that is healthy, happy, and fulfilling. Consequently, Vedic Astrology contains a wide range of remedial measures intended to significantly reduce the impact of returning negative karmas. These remedies help restore balance, harmony, and well-being.`, ja: `The Vedic tradition promotes a life that is healthy, happy, and fulfilling. Consequently, Vedic Astrology contains a wide range of remedial measures intended to significantly reduce the impact of returning negative karmas. These remedies help restore balance, harmony, and well-being.` } },
      { type: "paragraph", text: { en: `Their effectiveness is based on the understanding that we are all part of an interconnected whole. By participating in Vedic ceremonies such as Yagnas, Yagyas, or Homas, performing prescribed acts of charity, reciting specific Sanskrit mantras, or wearing suitable gemstones, it is believed that returning karmas can be modified or deflected to a considerable degree.`, ja: `Their effectiveness is based on the understanding that we are all part of an interconnected whole. By participating in Vedic ceremonies such as Yagnas, Yagyas, or Homas, performing prescribed acts of charity, reciting specific Sanskrit mantras, or wearing suitable gemstones, it is believed that returning karmas can be modified or deflected to a considerable degree.` } },
      { type: "paragraph", text: { en: `As a result, an individual may not need to experience the full karmic consequences during the present lifetime. At the same time, Jyotish remedies can strengthen the beneficial effects of positive karmas. For this reason, Jyotish may rightly be considered the ultimate Karmic Engineering System.`, ja: `As a result, an individual may not need to experience the full karmic consequences during the present lifetime. At the same time, Jyotish remedies can strengthen the beneficial effects of positive karmas. For this reason, Jyotish may rightly be considered the ultimate Karmic Engineering System.` } },
      { type: "heading", level: 3, text: { en: `3. Spiritual Practices Deflect Negative Karma`, ja: `3. Spiritual Practices Deflect Negative Karma` } },
      { type: "paragraph", text: { en: `Returning karmas can also be profoundly influenced by the spiritual practices we undertake during this lifetime.`, ja: `Returning karmas can also be profoundly influenced by the spiritual practices we undertake during this lifetime.` } },
      { type: "paragraph", text: { en: `Most experienced Jyotish astrologers will agree that regular meditation and sadhana (spiritual practice) noticeably reduce the predicted effects of difficult karmas. Many spiritual Masters have taught that destiny itself can be transformed through daily meditation, chanting, pranayama, and related disciplines.`, ja: `Most experienced Jyotish astrologers will agree that regular meditation and sadhana (spiritual practice) noticeably reduce the predicted effects of difficult karmas. Many spiritual Masters have taught that destiny itself can be transformed through daily meditation, chanting, pranayama, and related disciplines.` } },
      { type: "paragraph", text: { en: `The great Spiritual Master Paramahansa Yogananda [5] affirmed this principle when he stated that as an individual moves "into the orbit of the Divine, they move out of the orbit of planetary influences."`, ja: `The great Spiritual Master Paramahansa Yogananda [5] affirmed this principle when he stated that as an individual moves "into the orbit of the Divine, they move out of the orbit of planetary influences."` } },
      { type: "paragraph", text: { en: `Those fortunate enough to have a Self-realized Spiritual Master (Guru) should also recognize the power of the Guru's Grace, which can remove major obstacles and greatly lessen the impact of returning negative karmas.`, ja: `Those fortunate enough to have a Self-realized Spiritual Master (Guru) should also recognize the power of the Guru's Grace, which can remove major obstacles and greatly lessen the impact of returning negative karmas.` } },
    ],
  },
  {
    id: "three-types-karma",
    section: "introduction",
    title: { en: `Three Types of Karma – Sanchita, Prarabdha and Agami`, ja: `Three Types of Karma – Sanchita, Prarabdha and Agami` },
    related: ["jyotish-and-karma","mahadashas","planetary-antidotes"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Three Types of Karma – Sanchita, Prarabdha and Agami`, ja: `Three Types of Karma – Sanchita, Prarabdha and Agami` } },
      { type: "paragraph", text: { en: `The Vedas clearly describe three primary categories of karma: Sanchita, Prarabdha, and Agami. Jyotish Astrology is primarily concerned with the Prarabdha aspect of karma [6]. However, when Self-realization is attained, all karmas associated with previous lives are transcended.`, ja: `The Vedas clearly describe three primary categories of karma: Sanchita, Prarabdha, and Agami. Jyotish Astrology is primarily concerned with the Prarabdha aspect of karma [6]. However, when Self-realization is attained, all karmas associated with previous lives are transcended.` } },
      { type: "paragraph", text: { en: `On a personal note: I have complete confidence in the effectiveness of Jyotish remedial measures for reducing suffering in this lifetime. Nevertheless, certain questions remain. Are we genuinely reducing karmas, or merely postponing them to a future incarnation? Can karma truly be modified in this way? Or does an individual possess sufficient positive karma within their karmic "storehouse"—their own karmic credit account—to encounter a Jyotish astrologer and receive guidance regarding these remedies in the first place? Such questions are perhaps best answered by an enlightened Master.`, ja: `On a personal note: I have complete confidence in the effectiveness of Jyotish remedial measures for reducing suffering in this lifetime. Nevertheless, certain questions remain. Are we genuinely reducing karmas, or merely postponing them to a future incarnation? Can karma truly be modified in this way? Or does an individual possess sufficient positive karma within their karmic "storehouse"—their own karmic credit account—to encounter a Jyotish astrologer and receive guidance regarding these remedies in the first place? Such questions are perhaps best answered by an enlightened Master.` } },
      { type: "heading", level: 3, text: { en: `Footnotes`, ja: `Footnotes` } },
      { type: "heading", level: 3, text: { en: `[1]`, ja: `[1]` } },
      { type: "paragraph", text: { en: `Samskaras are deep-rooted impressions and desires left within the mind by past actions, including those from previous lifetimes. In the Vedic understanding, the mind is not confined to the brain; rather, it extends beyond and surrounds the body. One Vedic pundit described these latent impressions as "post-it notes attached to the soul."`, ja: `Samskaras are deep-rooted impressions and desires left within the mind by past actions, including those from previous lifetimes. In the Vedic understanding, the mind is not confined to the brain; rather, it extends beyond and surrounds the body. One Vedic pundit described these latent impressions as "post-it notes attached to the soul."` } },
      { type: "paragraph", text: { en: `Karma is frequently illustrated as a wheel. Latent impressions in the mind generate actions, those actions create new impressions, and future actions are then influenced by those impressions. The process continues cyclically. Through meditation and spiritual practices, however, this cycle can be broken. Karma and samskara are therefore inseparably connected.`, ja: `Karma is frequently illustrated as a wheel. Latent impressions in the mind generate actions, those actions create new impressions, and future actions are then influenced by those impressions. The process continues cyclically. Through meditation and spiritual practices, however, this cycle can be broken. Karma and samskara are therefore inseparably connected.` } },
      { type: "heading", level: 3, text: { en: `[2]`, ja: `[2]` } },
      { type: "paragraph", text: { en: `What creates negative karma? One Vedic scholar explained it simply: "doing to others what we would not wish done to ourselves." This principle may reasonably be extended to our treatment of all living beings and the natural environment.`, ja: `What creates negative karma? One Vedic scholar explained it simply: "doing to others what we would not wish done to ourselves." This principle may reasonably be extended to our treatment of all living beings and the natural environment.` } },
      { type: "heading", level: 3, text: { en: `[3]`, ja: `[3]` } },
      { type: "paragraph", text: { en: `Karmic influences affecting every aspect of life are interpreted in Vedic Astrology through the positions of the nine planets within the twelve zodiac signs, twelve houses, and twenty-seven Nakshatras, as shown in a person's birth chart calculated using the sidereal zodiac.`, ja: `Karmic influences affecting every aspect of life are interpreted in Vedic Astrology through the positions of the nine planets within the twelve zodiac signs, twelve houses, and twenty-seven Nakshatras, as shown in a person's birth chart calculated using the sidereal zodiac.` } },
      { type: "heading", level: 3, text: { en: `[4]`, ja: `[4]` } },
      { type: "paragraph", text: { en: `The timing of karmic influences that are likely to become prominent in life is calculated through the Vimsottari Maha Dasha system, based on the natal position of the Moon within one of the twenty-seven Nakshatras.`, ja: `The timing of karmic influences that are likely to become prominent in life is calculated through the Vimsottari Maha Dasha system, based on the natal position of the Moon within one of the twenty-seven Nakshatras.` } },
      { type: "heading", level: 3, text: { en: `[5]`, ja: `[5]` } },
      { type: "paragraph", text: { en: `Paramahansa Yogananda (1893–1952) was a Self-realized sage who spent a significant portion of his life in the West teaching yoga and Vedic philosophy. His most widely read and highly recommended work is the Autobiography of a Yogi, published by the Yogoda Satsanga Society of India.`, ja: `Paramahansa Yogananda (1893–1952) was a Self-realized sage who spent a significant portion of his life in the West teaching yoga and Vedic philosophy. His most widely read and highly recommended work is the Autobiography of a Yogi, published by the Yogoda Satsanga Society of India.` } },
      { type: "paragraph", text: { en: `2013 Edition: ISBN-10: 818953551X`, ja: `2013 Edition: ISBN-10: 818953551X` } },
      { type: "paragraph", text: { en: `ISBN-13: 978-8189535513`, ja: `ISBN-13: 978-8189535513` } },
      { type: "heading", level: 3, text: { en: `[6]`, ja: `[6]` } },
      { type: "heading", level: 3, text: { en: `Categories of Karma`, ja: `Categories of Karma` } },
      { type: "paragraph", text: { en: `• Sanchita – The accumulated storehouse of all karmas from previous births.`, ja: `• Sanchita – The accumulated storehouse of all karmas from previous births.` } },
      { type: "paragraph", text: { en: `• Prarabdha – The portion of Sanchita karma that must be experienced and worked through in the current lifetime. It is often said that Prarabdha karma is best suited to support our evolutionary growth in this incarnation.`, ja: `• Prarabdha – The portion of Sanchita karma that must be experienced and worked through in the current lifetime. It is often said that Prarabdha karma is best suited to support our evolutionary growth in this incarnation.` } },
      { type: "paragraph", text: { en: `• Agami – The new karma generated in this lifetime that will be carried forward into future incarnations.`, ja: `• Agami – The new karma generated in this lifetime that will be carried forward into future incarnations.` } },
      { type: "paragraph", text: { en: `Jyotish – Sidereal Zodiac`, ja: `Jyotish – Sidereal Zodiac` } },
      { type: "paragraph", text: { en: `Summary: This article explores the differences between the zodiacs used in Vedic Astrology and Western Astrology. It explains why Jyotish relies on the fixed Sidereal Zodiac rather than the movable Tropical Zodiac, thereby addressing one of the main objections astronomers raise against astrology. The article also illustrates how Sun signs, Ascendants, and planetary positions can appear in different zodiac signs when calculated using these two systems.`, ja: `Summary: This article explores the differences between the zodiacs used in Vedic Astrology and Western Astrology. It explains why Jyotish relies on the fixed Sidereal Zodiac rather than the movable Tropical Zodiac, thereby addressing one of the main objections astronomers raise against astrology. The article also illustrates how Sun signs, Ascendants, and planetary positions can appear in different zodiac signs when calculated using these two systems.` } },
      { type: "heading", level: 3, text: { en: `Jyotish Uses the Fixed Sidereal Zodiac`, ja: `Jyotish Uses the Fixed Sidereal Zodiac` } },
      { type: "paragraph", text: { en: `Jyotish Astrology employs a different zodiac system from the one commonly used in Western Astrology.`, ja: `Jyotish Astrology employs a different zodiac system from the one commonly used in Western Astrology.` } },
      { type: "paragraph", text: { en: `Both Jyotish and Western Astrology are based on an imaginary celestial sphere surrounding the Earth. In each system, this sphere is divided into twelve equal sections of 30 degrees each, much like the segments of an orange. The same zodiac sign names—Aries, Taurus, Gemini, and so on—are used in both traditions. The Sun appears to move through each zodiac sign in approximately one month.`, ja: `Both Jyotish and Western Astrology are based on an imaginary celestial sphere surrounding the Earth. In each system, this sphere is divided into twelve equal sections of 30 degrees each, much like the segments of an orange. The same zodiac sign names—Aries, Taurus, Gemini, and so on—are used in both traditions. The Sun appears to move through each zodiac sign in approximately one month.` } },
      { type: "paragraph", text: { en: `Jyotish uses the fixed, or Sidereal Zodiac. The term sidereal means "with respect to the stars." The starting point of the Sidereal Zodiac is permanently fixed using the background of the seemingly non-moving stars within our galaxy as a reference [1]. As a result, the zodiac signs remain consistently aligned with the stellar constellations. The beginning of the first sign, Aries, therefore remains fixed in Vedic Astrology, and all the other zodiac signs maintain their permanent relationship to the distant background stars.`, ja: `Jyotish uses the fixed, or Sidereal Zodiac. The term sidereal means "with respect to the stars." The starting point of the Sidereal Zodiac is permanently fixed using the background of the seemingly non-moving stars within our galaxy as a reference [1]. As a result, the zodiac signs remain consistently aligned with the stellar constellations. The beginning of the first sign, Aries, therefore remains fixed in Vedic Astrology, and all the other zodiac signs maintain their permanent relationship to the distant background stars.` } },
      { type: "paragraph", text: { en: `Western Astrology, by contrast, uses the Tropical Zodiac, which is movable. The starting point of this zodiac gradually shifts relative to the background of the fixed stars because it is tied to the position of the equinox. This movement occurs due to the astronomically observed phenomenon known as the precession of the equinoxes [2].`, ja: `Western Astrology, by contrast, uses the Tropical Zodiac, which is movable. The starting point of this zodiac gradually shifts relative to the background of the fixed stars because it is tied to the position of the equinox. This movement occurs due to the astronomically observed phenomenon known as the precession of the equinoxes [2].` } },
      { type: "paragraph", text: { en: `Consequently, in Western Astrology the sign referred to as Aries slowly changes its position in the sky relative to the fixed stars over long periods of time. It is not permanently connected to a specific stellar constellation. Many people, including students of Western Astrology, find this fact quite surprising when they first encounter it.`, ja: `Consequently, in Western Astrology the sign referred to as Aries slowly changes its position in the sky relative to the fixed stars over long periods of time. It is not permanently connected to a specific stellar constellation. Many people, including students of Western Astrology, find this fact quite surprising when they first encounter it.` } },
      { type: "paragraph", text: { en: `Astronomers frequently criticize Western Astrology because the Tropical Zodiac moves relative to the fixed stars. Since the position of Aries gradually shifts over time, they question the validity of associating it with a fixed area of the sky. However, this criticism does not apply to Jyotish because it uses a fixed Sidereal Zodiac rather than a movable one.`, ja: `Astronomers frequently criticize Western Astrology because the Tropical Zodiac moves relative to the fixed stars. Since the position of Aries gradually shifts over time, they question the validity of associating it with a fixed area of the sky. However, this criticism does not apply to Jyotish because it uses a fixed Sidereal Zodiac rather than a movable one.` } },
      { type: "heading", level: 3, text: { en: `Ayanamsa – Angular Difference Between the Two Zodiacs`, ja: `Ayanamsa – Angular Difference Between the Two Zodiacs` } },
      { type: "paragraph", text: { en: `The angular separation between the Sidereal and Tropical zodiacs is known as the ayanamsa (ayanāṃśa or ayanamsha), and this difference increases gradually over time [3]. Although both zodiacs were approximately aligned around 1,700 years ago, the Tropical Zodiac used by Western astrologers has since shifted away from that original position.`, ja: `The angular separation between the Sidereal and Tropical zodiacs is known as the ayanamsa (ayanāṃśa or ayanamsha), and this difference increases gradually over time [3]. Although both zodiacs were approximately aligned around 1,700 years ago, the Tropical Zodiac used by Western astrologers has since shifted away from that original position.` } },
      { type: "paragraph", text: { en: `As of 2021, the difference between the two zodiacs is approximately 24 degrees. Therefore, if the Sun is positioned at 29 degrees Virgo in the Tropical Zodiac, it will be located at approximately 29° – 24° = 5° Virgo in the Sidereal Zodiac. In this example, the Sun remains in Virgo in both systems.`, ja: `As of 2021, the difference between the two zodiacs is approximately 24 degrees. Therefore, if the Sun is positioned at 29 degrees Virgo in the Tropical Zodiac, it will be located at approximately 29° – 24° = 5° Virgo in the Sidereal Zodiac. In this example, the Sun remains in Virgo in both systems.` } },
      { type: "paragraph", text: { en: `However, if the Sun lies between 0° and 24° Virgo in the Tropical Zodiac, it will fall into Leo in the Sidereal Zodiac used by Vedic Astrology. In other words, it moves backwards (anti-clockwise) by the amount of the ayanamsa—around 24 degrees—and enters the previous sign [4].`, ja: `However, if the Sun lies between 0° and 24° Virgo in the Tropical Zodiac, it will fall into Leo in the Sidereal Zodiac used by Vedic Astrology. In other words, it moves backwards (anti-clockwise) by the amount of the ayanamsa—around 24 degrees—and enters the previous sign [4].` } },
      { type: "paragraph", text: { en: `This means that a person's Sun sign may differ between the two systems. Someone considered a Virgo in Western Astrology may actually be a Leo according to Jyotish. The same principle applies not only to the Sun but also to all planetary positions and the Ascendant. These sign differences can help explain many of the inconsistencies and anomalies encountered when charts are interpreted solely through modern Western Astrology.`, ja: `This means that a person's Sun sign may differ between the two systems. Someone considered a Virgo in Western Astrology may actually be a Leo according to Jyotish. The same principle applies not only to the Sun but also to all planetary positions and the Ascendant. These sign differences can help explain many of the inconsistencies and anomalies encountered when charts are interpreted solely through modern Western Astrology.` } },
    ],
  },
  {
    id: "nakshatras-stellar-1",
    section: "nakshatras",
    title: { en: `Nakshatras – Stellar Constellations`, ja: `Nakshatras – Stellar Constellations` },
    related: ["sidereal-zodiac-p3","mahadashas","twelve-houses"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Nakshatras – Stellar Constellations`, ja: `Nakshatras – Stellar Constellations` } },
      { type: "paragraph", text: { en: `Jyotish places considerable importance on the stellar constellations known as Nakshatras. They play a vital role in chart interpretation, compatibility analysis, and determining favourable timings for important activities through Muhurtha.`, ja: `Jyotish places considerable importance on the stellar constellations known as Nakshatras. They play a vital role in chart interpretation, compatibility analysis, and determining favourable timings for important activities through Muhurtha.` } },
      { type: "paragraph", text: { en: `There are 27 Nakshatras, often referred to as Lunar Mansions, distributed evenly throughout the sky. Technically speaking, they are arranged as equal sectors along the ecliptic.`, ja: `There are 27 Nakshatras, often referred to as Lunar Mansions, distributed evenly throughout the sky. Technically speaking, they are arranged as equal sectors along the ecliptic.` } },
      { type: "paragraph", text: { en: `Given the significance of the Nakshatras within Vedic Astrology, it is hardly surprising that Jyotish employs a zodiac system that remains permanently anchored to the fixed stars and therefore remains aligned with the Nakshatras themselves.`, ja: `Given the significance of the Nakshatras within Vedic Astrology, it is hardly surprising that Jyotish employs a zodiac system that remains permanently anchored to the fixed stars and therefore remains aligned with the Nakshatras themselves.` } },
      { type: "heading", level: 3, text: { en: `Footnotes`, ja: `Footnotes` } },
      { type: "heading", level: 3, text: { en: `[1]`, ja: `[1]` } },
      { type: "paragraph", text: { en: `The "fixed stars" are located so far from Earth that their angular movement relative to our Sun is extremely small, even across many thousands of years. For practical purposes, it is therefore reasonable to describe them as fixed or immovable.`, ja: `The "fixed stars" are located so far from Earth that their angular movement relative to our Sun is extremely small, even across many thousands of years. For practical purposes, it is therefore reasonable to describe them as fixed or immovable.` } },
      { type: "heading", level: 3, text: { en: `[2]`, ja: `[2]` } },
      { type: "paragraph", text: { en: `The equinox point on Earth's orbit around the Sun gradually shifts relative to the background of the fixed stars due to a phenomenon known as the precession of the equinoxes. This well-established astronomical effect results from a slight wobble in Earth's rotational axis, similar to the motion of a spinning top whose axis slowly traces out a cone-shaped path. Earth takes approximately 26,000 years to complete one full precessional cycle.`, ja: `The equinox point on Earth's orbit around the Sun gradually shifts relative to the background of the fixed stars due to a phenomenon known as the precession of the equinoxes. This well-established astronomical effect results from a slight wobble in Earth's rotational axis, similar to the motion of a spinning top whose axis slowly traces out a cone-shaped path. Earth takes approximately 26,000 years to complete one full precessional cycle.` } },
      { type: "heading", level: 3, text: { en: `[3]`, ja: `[3]` } },
      { type: "paragraph", text: { en: `As of 2021, the angular difference between the Tropical and Sidereal zodiacs is approximately 24 degrees. This value, or one very close to it, was derived by Lahiri and is widely accepted among Jyotish astrologers. Most modern astrological tables therefore use Lahiri's ayanamsa.`, ja: `As of 2021, the angular difference between the Tropical and Sidereal zodiacs is approximately 24 degrees. This value, or one very close to it, was derived by Lahiri and is widely accepted among Jyotish astrologers. Most modern astrological tables therefore use Lahiri's ayanamsa.` } },
      { type: "paragraph", text: { en: `The Tropical Zodiac moves relative to the Sidereal (fixed) Zodiac at a rate of approximately one degree every 71 years. Although this shift may appear small, it was observed by ancient Egyptian astronomers thousands of years ago. Over long periods, the accumulated effect becomes highly significant.`, ja: `The Tropical Zodiac moves relative to the Sidereal (fixed) Zodiac at a rate of approximately one degree every 71 years. Although this shift may appear small, it was observed by ancient Egyptian astronomers thousands of years ago. Over long periods, the accumulated effect becomes highly significant.` } },
      { type: "heading", level: 3, text: { en: `[4]`, ja: `[4]` } },
      { type: "paragraph", text: { en: `The difference in planetary positions between the two zodiac systems is currently about 24 degrees. For example, if the Sun is positioned at 14 degrees Virgo in Western Astrology, its Sidereal position would be calculated as:`, ja: `The difference in planetary positions between the two zodiac systems is currently about 24 degrees. For example, if the Sun is positioned at 14 degrees Virgo in Western Astrology, its Sidereal position would be calculated as:` } },
      { type: "paragraph", text: { en: `14° – 24° = –10° Virgo`, ja: `14° – 24° = –10° Virgo` } },
      { type: "paragraph", text: { en: `This indicates that the Sun is actually 10 degrees before the start of Virgo. In practical terms, it has moved backwards (anti-clockwise) into the previous sign, Leo, where its position becomes 20 degrees Leo (since –10 + 30 = 20).`, ja: `This indicates that the Sun is actually 10 degrees before the start of Virgo. In practical terms, it has moved backwards (anti-clockwise) into the previous sign, Leo, where its position becomes 20 degrees Leo (since –10 + 30 = 20).` } },
      { type: "paragraph", text: { en: `By contrast, if the Sun is located at 28 degrees Virgo in the Tropical Zodiac, the calculation becomes:`, ja: `By contrast, if the Sun is located at 28 degrees Virgo in the Tropical Zodiac, the calculation becomes:` } },
      { type: "paragraph", text: { en: `28° – 24° = 4° Virgo`, ja: `28° – 24° = 4° Virgo` } },
      { type: "paragraph", text: { en: `Although the Sun has still shifted backwards by the ayanamsa amount, it remains within Virgo and therefore does not change signs.`, ja: `Although the Sun has still shifted backwards by the ayanamsa amount, it remains within Virgo and therefore does not change signs.` } },
    ],
  },
  {
    id: "planetary-forces",
    section: "introduction",
    title: { en: `Jyotish – Planetary Forces`, ja: `Jyotish – Planetary Forces` },
    related: ["natural-benefics-malefics","planetary-strengths","origins-of-jyotish"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Jyotish – Planetary Forces`, ja: `Jyotish – Planetary Forces` } },
      { type: "paragraph", text: { en: `Summary: This article addresses a common criticism made by some Western Astrologers regarding traditional Vedic Astrology—that it is limited or outdated because it uses only nine "planets." Jyotish maintains that there is no need to incorporate planets beyond Saturn, as it works directly with a field of perfectly codified information rather than with physical or subtle forces supposedly emitted by planets, asteroids, or other celestial bodies.`, ja: `Summary: This article addresses a common criticism made by some Western Astrologers regarding traditional Vedic Astrology—that it is limited or outdated because it uses only nine "planets." Jyotish maintains that there is no need to incorporate planets beyond Saturn, as it works directly with a field of perfectly codified information rather than with physical or subtle forces supposedly emitted by planets, asteroids, or other celestial bodies.` } },
      { type: "paragraph", text: { en: `Planetary ‘Forces’ Don’t Exist in Vedic Astrology`, ja: `Planetary ‘Forces’ Don’t Exist in Vedic Astrology` } },
      { type: "paragraph", text: { en: `Many Western Astrologers hold the view that planets—and even asteroids—emit some form of subtle influence or force, which has not yet been identified by modern science, and that these forces affect human life. Based on this assumption, they often argue that Jyotish Astrology is incomplete because it does not include the outer planets Uranus, Neptune, and Pluto, nor more recently recognized celestial objects such as Chiron.`, ja: `Many Western Astrologers hold the view that planets—and even asteroids—emit some form of subtle influence or force, which has not yet been identified by modern science, and that these forces affect human life. Based on this assumption, they often argue that Jyotish Astrology is incomplete because it does not include the outer planets Uranus, Neptune, and Pluto, nor more recently recognized celestial objects such as Chiron.` } },
      { type: "paragraph", text: { en: `However, as discussed below, Vedic Astrology approaches the subject from an entirely different perspective. Jyotish works directly with a field of structured and codified information that is complete in itself, rather than with any form of planetary force.`, ja: `However, as discussed below, Vedic Astrology approaches the subject from an entirely different perspective. Jyotish works directly with a field of structured and codified information that is complete in itself, rather than with any form of planetary force.` } },
      { type: "paragraph", text: { en: `Although Vedic Astrologers may occasionally use the phrase "planetary force" when communicating with clients, this should not be interpreted as referring to an actual physical force. Instead, it simply describes the influence or effect that a planet signifies within an individual's life.`, ja: `Although Vedic Astrologers may occasionally use the phrase "planetary force" when communicating with clients, this should not be interpreted as referring to an actual physical force. Instead, it simply describes the influence or effect that a planet signifies within an individual's life.` } },
      { type: "heading", level: 3, text: { en: `Key Points in Support of the ‘Codified Information’ Viewpoint`, ja: `Key Points in Support of the ‘Codified Information’ Viewpoint` } },
      { type: "paragraph", text: { en: `• Jyotish regards the planetary arrangements present at the moment of birth as a form of cosmic code. Skilled Vedic Astrologers interpret this code and translate it into predictions concerning returning karma carried over from previous incarnations.`, ja: `• Jyotish regards the planetary arrangements present at the moment of birth as a form of cosmic code. Skilled Vedic Astrologers interpret this code and translate it into predictions concerning returning karma carried over from previous incarnations.` } },
      { type: "paragraph", text: { en: `• The placement of the seven visible planets (up to and including Saturn), together with the two lunar nodes [1], within the twelve signs, twelve houses, and twenty-seven Nakshatras, represents a highly sophisticated system of encoded information. This information provides everything required for understanding the major areas of life—Dharma, Artha, Kama, and Moksha.`, ja: `• The placement of the seven visible planets (up to and including Saturn), together with the two lunar nodes [1], within the twelve signs, twelve houses, and twenty-seven Nakshatras, represents a highly sophisticated system of encoded information. This information provides everything required for understanding the major areas of life—Dharma, Artha, Kama, and Moksha.` } },
      { type: "paragraph", text: { en: `• Planetary transits, as planets appear to move through the sidereal zodiac signs and houses, are likewise viewed as expressions of codified information rather than manifestations of physical forces.`, ja: `• Planetary transits, as planets appear to move through the sidereal zodiac signs and houses, are likewise viewed as expressions of codified information rather than manifestations of physical forces.` } },
      { type: "paragraph", text: { en: `• The absence of any physical force is further supported by a fundamental Jyotish principle: the effects of planets vary significantly according to an individual's Ascendant or rising sign [2]. No comparable concept exists within traditional Western Astrology. The same planet can produce very different outcomes depending upon the Ascendant. If a genuine physical force were involved, such variations would be difficult to explain.`, ja: `• The absence of any physical force is further supported by a fundamental Jyotish principle: the effects of planets vary significantly according to an individual's Ascendant or rising sign [2]. No comparable concept exists within traditional Western Astrology. The same planet can produce very different outcomes depending upon the Ascendant. If a genuine physical force were involved, such variations would be difficult to explain.` } },
      { type: "paragraph", text: { en: `• Jyotish also places great importance on Rahu and Ketu, the Moon's nodes. These have no physical substance whatsoever. They are simply mathematically calculated points where the Moon's orbit intersects the ecliptic [3]. Yet they indicate major karmic influences and tangible life experiences. If these points possess no material existence, it becomes difficult to argue that their effects result from any physical force.`, ja: `• Jyotish also places great importance on Rahu and Ketu, the Moon's nodes. These have no physical substance whatsoever. They are simply mathematically calculated points where the Moon's orbit intersects the ecliptic [3]. Yet they indicate major karmic influences and tangible life experiences. If these points possess no material existence, it becomes difficult to argue that their effects result from any physical force.` } },
      { type: "paragraph", text: { en: `• Vedic Astrologers traditionally believe that Jyotish was "revealed" or "cognized." It was neither invented by humanity nor developed gradually through experimentation. Rather, it is regarded as Divine Knowledge that is complete in itself. Within this divine system there is no requirement to incorporate information from the outer planets or recently discovered asteroids. To do so would be viewed as a departure from the original teachings of the great sage Maharishi Parashara.`, ja: `• Vedic Astrologers traditionally believe that Jyotish was "revealed" or "cognized." It was neither invented by humanity nor developed gradually through experimentation. Rather, it is regarded as Divine Knowledge that is complete in itself. Within this divine system there is no requirement to incorporate information from the outer planets or recently discovered asteroids. To do so would be viewed as a departure from the original teachings of the great sage Maharishi Parashara.` } },
      { type: "paragraph", text: { en: `• The idea of complete and perfect knowledge being provided by the Divine for the benefit of humanity is not unique to Jyotish. Similar principles are found in other Vedic sciences such as Ayurveda, the Vedic system of natural healthcare, and Vastu, the science of designing harmonious living environments.`, ja: `• The idea of complete and perfect knowledge being provided by the Divine for the benefit of humanity is not unique to Jyotish. Similar principles are found in other Vedic sciences such as Ayurveda, the Vedic system of natural healthcare, and Vastu, the science of designing harmonious living environments.` } },
      { type: "heading", level: 3, text: { en: `Jyotish Astrologers Interpret the ‘Cosmic Codes’`, ja: `Jyotish Astrologers Interpret the ‘Cosmic Codes’` } },
      { type: "paragraph", text: { en: `To fully appreciate the foundations of Jyotish, we must move beyond purely mechanistic models of reality. The traditional Newtonian view, based on objects and forces, gives way to a deeper understanding in which consciousness is regarded as the fundamental basis of existence. At its core, the functioning of Vedic Astrology rests upon the Vedic model of reality.`, ja: `To fully appreciate the foundations of Jyotish, we must move beyond purely mechanistic models of reality. The traditional Newtonian view, based on objects and forces, gives way to a deeper understanding in which consciousness is regarded as the fundamental basis of existence. At its core, the functioning of Vedic Astrology rests upon the Vedic model of reality.` } },
      { type: "paragraph", text: { en: `Jyotish emerges from a tradition that views the universe as one perfectly integrated whole. Underlying this totality is an all-pervading field of Cosmic Intelligence. In our essential nature, we are part of that Cosmic Intelligence. It is therefore not surprising that the intelligence responsible for creating the universe should also provide insights into our past, present, and potential future.`, ja: `Jyotish emerges from a tradition that views the universe as one perfectly integrated whole. Underlying this totality is an all-pervading field of Cosmic Intelligence. In our essential nature, we are part of that Cosmic Intelligence. It is therefore not surprising that the intelligence responsible for creating the universe should also provide insights into our past, present, and potential future.` } },
      { type: "paragraph", text: { en: `As the enlightened Vedic Master Sri Sri Ravi Shankar stated:`, ja: `As the enlightened Vedic Master Sri Sri Ravi Shankar stated:` } },
      { type: "paragraph", text: { en: `"The purpose of astrology is to take you to the ultimate truth that the entire universe is one organism. It's one Being, one consciousness, one Self, that manifests itself into this varied universe."`, ja: `"The purpose of astrology is to take you to the ultimate truth that the entire universe is one organism. It's one Being, one consciousness, one Self, that manifests itself into this varied universe."` } },
      { type: "paragraph", text: { en: `(Published in the Art of Living's Daily Sutra, May 2003.)`, ja: `(Published in the Art of Living's Daily Sutra, May 2003.)` } },
      { type: "paragraph", text: { en: `In many respects, a birth chart can be compared to a strand of DNA within a sperm or egg cell. DNA stores vast amounts of information in an extremely condensed form. As time unfolds, that information is progressively expressed as tissues, organs, physical structures, and eventually a complete living being.`, ja: `In many respects, a birth chart can be compared to a strand of DNA within a sperm or egg cell. DNA stores vast amounts of information in an extremely condensed form. As time unfolds, that information is progressively expressed as tissues, organs, physical structures, and eventually a complete living being.` } },
      { type: "paragraph", text: { en: `A similar process occurs in Jyotish. The information encoded within a birth chart gradually unfolds through time, manifesting as significant life events and karmic experiences—whether beneficial or challenging.`, ja: `A similar process occurs in Jyotish. The information encoded within a birth chart gradually unfolds through time, manifesting as significant life events and karmic experiences—whether beneficial or challenging.` } },
      { type: "paragraph", text: { en: `Jyotish Astrology consists of numerous axioms and mathematical rules that enable the astrologer to interpret how the highly encoded information within a birth chart may unfold into physical circumstances and karmic outcomes. This process is somewhat analogous to modern biochemistry, which can decode sections of DNA and relate them to recognizable physical characteristics.`, ja: `Jyotish Astrology consists of numerous axioms and mathematical rules that enable the astrologer to interpret how the highly encoded information within a birth chart may unfold into physical circumstances and karmic outcomes. This process is somewhat analogous to modern biochemistry, which can decode sections of DNA and relate them to recognizable physical characteristics.` } },
      { type: "paragraph", text: { en: `For this reason, Jyotish does not require the concept of forces being emitted by planets or celestial bodies. It works directly with a field of information and intelligence that is already complete and self-contained.`, ja: `For this reason, Jyotish does not require the concept of forces being emitted by planets or celestial bodies. It works directly with a field of information and intelligence that is already complete and self-contained.` } },
      { type: "heading", level: 3, text: { en: `Footnotes`, ja: `Footnotes` } },
      { type: "heading", level: 3, text: { en: `[1]`, ja: `[1]` } },
      { type: "paragraph", text: { en: `Jyotish utilizes nine Grahas, or celestial influences, often translated as "planets." These include the Sun and Moon (which are not classified as planets from an astronomical perspective), Mercury, Venus, Mars, Jupiter, and Saturn. It also includes two calculated points known as Rahu and Ketu, the Moon's nodes, which are closely associated with eclipses.`, ja: `Jyotish utilizes nine Grahas, or celestial influences, often translated as "planets." These include the Sun and Moon (which are not classified as planets from an astronomical perspective), Mercury, Venus, Mars, Jupiter, and Saturn. It also includes two calculated points known as Rahu and Ketu, the Moon's nodes, which are closely associated with eclipses.` } },
      { type: "heading", level: 3, text: { en: `[2]`, ja: `[2]` } },
      { type: "paragraph", text: { en: `For example, in Jyotish the planet Mars is generally considered highly beneficial in the birth chart of an individual with a Leo Ascendant because it rules both the 4th house and the auspicious 9th house, thereby functioning as a functional benefic.`, ja: `For example, in Jyotish the planet Mars is generally considered highly beneficial in the birth chart of an individual with a Leo Ascendant because it rules both the 4th house and the auspicious 9th house, thereby functioning as a functional benefic.` } },
      { type: "paragraph", text: { en: `By contrast, Mars is generally regarded as strongly unfavourable for someone with a Virgo Ascendant because it rules the 6th and 11th houses, making it both a functional and natural malefic.`, ja: `By contrast, Mars is generally regarded as strongly unfavourable for someone with a Virgo Ascendant because it rules the 6th and 11th houses, making it both a functional and natural malefic.` } },
      { type: "paragraph", text: { en: `Thus, the same planet can indicate positive outcomes for one individual and negative outcomes for another. Clearly, this cannot be explained by a physical force emanating from Mars itself. Rather, it supports the view that Jyotish operates through an integrated field of information or intelligence linking the individual to the Cosmic Totality.`, ja: `Thus, the same planet can indicate positive outcomes for one individual and negative outcomes for another. Clearly, this cannot be explained by a physical force emanating from Mars itself. Rather, it supports the view that Jyotish operates through an integrated field of information or intelligence linking the individual to the Cosmic Totality.` } },
      { type: "heading", level: 3, text: { en: `[3]`, ja: `[3]` } },
      { type: "paragraph", text: { en: `"The lunar nodes are the orbital nodes of the Moon, that is, the two points at which the orbit of the Moon crosses the ecliptic. The ascending (or north) node is where the Moon moves into the northern ecliptic hemisphere, while the descending (or south) node is where the Moon enters the southern ecliptic hemisphere. Eclipses involving the Moon occur only near the lunar nodes. A solar eclipse occurs when the passage of the Moon through a node coincides with the new moon, while a lunar eclipse occurs when the passage coincides with the full moon."`, ja: `"The lunar nodes are the orbital nodes of the Moon, that is, the two points at which the orbit of the Moon crosses the ecliptic. The ascending (or north) node is where the Moon moves into the northern ecliptic hemisphere, while the descending (or south) node is where the Moon enters the southern ecliptic hemisphere. Eclipses involving the Moon occur only near the lunar nodes. A solar eclipse occurs when the passage of the Moon through a node coincides with the new moon, while a lunar eclipse occurs when the passage coincides with the full moon."` } },
    ],
  },
  {
    id: "forecasting-analogies-1",
    section: "introduction",
    title: { en: `Jyotish – Forecasting Analogies`, ja: `Jyotish – Forecasting Analogies` },
    related: ["predictive-capabilities","cosmos-individual-1","jyotish-and-karma"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Jyotish – Forecasting Analogies`, ja: `Jyotish – Forecasting Analogies` } },
      { type: "paragraph", text: { en: `Summary: This article explores several analogies commonly used to explain the probabilistic nature of prediction in Vedic Astrology. These comparisons help illustrate how planetary arrangements can be used to assess the likelihood of future events and influences unfolding in an individual's life.`, ja: `Summary: This article explores several analogies commonly used to explain the probabilistic nature of prediction in Vedic Astrology. These comparisons help illustrate how planetary arrangements can be used to assess the likelihood of future events and influences unfolding in an individual's life.` } },
      { type: "heading", level: 3, text: { en: `Forecasting Analogies in Vedic Astrology`, ja: `Forecasting Analogies in Vedic Astrology` } },
      { type: "heading", level: 3, text: { en: `Weather Forecasting Analogy`, ja: `Weather Forecasting Analogy` } },
      { type: "paragraph", text: { en: `Vedic Astrology is fundamentally probabilistic in nature. In this respect, it can be compared to a long-range weather forecasting system. Jyotish seeks to predict when and how the actions we have performed in the past—our accumulated karmas—are likely to return as present and future influences in our lives.`, ja: `Vedic Astrology is fundamentally probabilistic in nature. In this respect, it can be compared to a long-range weather forecasting system. Jyotish seeks to predict when and how the actions we have performed in the past—our accumulated karmas—are likely to return as present and future influences in our lives.` } },
      { type: "paragraph", text: { en: `If potential "storms" can be seen approaching on the horizon, we have the opportunity to take appropriate action and reduce difficulties before they fully manifest. Likewise, when "fine weather" is indicated, we can move forward more easily, make progress, and fulfil our desires with less resistance.`, ja: `If potential "storms" can be seen approaching on the horizon, we have the opportunity to take appropriate action and reduce difficulties before they fully manifest. Likewise, when "fine weather" is indicated, we can move forward more easily, make progress, and fulfil our desires with less resistance.` } },
      { type: "paragraph", text: { en: `Just as meteorologists cannot guarantee 100% accuracy in every forecast, Jyotish is not an exact science. Experienced and skilled Vedic Astrologers are generally considered capable of achieving prediction accuracies in the region of 70%. However, when numerous factors within a birth chart consistently point toward benefits or challenges in a particular area of life, the astrologer can make predictions with a much greater degree of confidence.`, ja: `Just as meteorologists cannot guarantee 100% accuracy in every forecast, Jyotish is not an exact science. Experienced and skilled Vedic Astrologers are generally considered capable of achieving prediction accuracies in the region of 70%. However, when numerous factors within a birth chart consistently point toward benefits or challenges in a particular area of life, the astrologer can make predictions with a much greater degree of confidence.` } },
      { type: "heading", level: 3, text: { en: `Seed Development Analogy`, ja: `Seed Development Analogy` } },
      { type: "paragraph", text: { en: `Different seeds produce different types of trees. A botanist can examine two seeds and confidently predict that one will develop into a silver birch and the other into a redwood. Most people find nothing unusual about such a prediction.`, ja: `Different seeds produce different types of trees. A botanist can examine two seeds and confidently predict that one will develop into a silver birch and the other into a redwood. Most people find nothing unusual about such a prediction.` } },
      { type: "paragraph", text: { en: `The botanist cannot determine exactly how many branches each tree will eventually have, nor can he state its precise height, since these factors depend upon soil quality, climate, and environmental conditions. Likewise, he cannot predict the exact lifespan of each tree. Nevertheless, he can accurately describe their general characteristics and growth patterns.`, ja: `The botanist cannot determine exactly how many branches each tree will eventually have, nor can he state its precise height, since these factors depend upon soil quality, climate, and environmental conditions. Likewise, he cannot predict the exact lifespan of each tree. Nevertheless, he can accurately describe their general characteristics and growth patterns.` } },
      { type: "paragraph", text: { en: `A birth chart can be viewed in much the same way as a seed. Therefore, it should not be surprising that Vedic Astrologers are able to predict broad life trends and tendencies.`, ja: `A birth chart can be viewed in much the same way as a seed. Therefore, it should not be surprising that Vedic Astrologers are able to predict broad life trends and tendencies.` } },
      { type: "paragraph", text: { en: `We know that the structure and characteristic development of a tree are encoded within the DNA contained in its seed. In a similar manner, the probable effects of our returning karmas—which themselves unfold according to the laws of nature—are reflected in the "code" contained within the planetary arrangements of the birth chart.`, ja: `We know that the structure and characteristic development of a tree are encoded within the DNA contained in its seed. In a similar manner, the probable effects of our returning karmas—which themselves unfold according to the laws of nature—are reflected in the "code" contained within the planetary arrangements of the birth chart.` } },
      { type: "paragraph", text: { en: `This viewpoint suggests that our time of birth is not merely a random event. Instead, it reflects the Vedic understanding that all life and matter are interconnected within a unified universe.`, ja: `This viewpoint suggests that our time of birth is not merely a random event. Instead, it reflects the Vedic understanding that all life and matter are interconnected within a unified universe.` } },
      { type: "heading", level: 3, text: { en: `Road Map Analogy`, ja: `Road Map Analogy` } },
      { type: "paragraph", text: { en: `Vedic Astrology offers a perspective that transcends ordinary limitations of space and time. Rather than travelling along an unfamiliar road without guidance, it provides a view from above—almost as if observing the journey from a helicopter.`, ja: `Vedic Astrology offers a perspective that transcends ordinary limitations of space and time. Rather than travelling along an unfamiliar road without guidance, it provides a view from above—almost as if observing the journey from a helicopter.` } },
      { type: "paragraph", text: { en: `From this higher vantage point, future turns, changes in terrain, and road conditions become visible before we encounter them. It is similar to navigating with a map instead of attempting to find the way without one.`, ja: `From this higher vantage point, future turns, changes in terrain, and road conditions become visible before we encounter them. It is similar to navigating with a map instead of attempting to find the way without one.` } },
      { type: "paragraph", text: { en: `Certain areas of life may resemble smooth, straight roads where progress comes easily. Other areas may contain bends, obstacles, or difficult terrain that require greater attention and care. These favourable and challenging periods also change over time as we move through life's journey.`, ja: `Certain areas of life may resemble smooth, straight roads where progress comes easily. Other areas may contain bends, obstacles, or difficult terrain that require greater attention and care. These favourable and challenging periods also change over time as we move through life's journey.` } },
      { type: "paragraph", text: { en: `Having access to the perspective offered by Vedic Astrology can therefore make life easier to navigate and potentially more fulfilling, as it helps us understand what may lie ahead and prepare accordingly.`, ja: `Having access to the perspective offered by Vedic Astrology can therefore make life easier to navigate and potentially more fulfilling, as it helps us understand what may lie ahead and prepare accordingly.` } },
    ],
  },
  {
    id: "cosmos-individual-1",
    section: "introduction",
    title: { en: `Relationship Between the Cosmos and the Individual`, ja: `Relationship Between the Cosmos and the Individual` },
    related: ["forecasting-analogies-1","planetary-forces","origins-of-jyotish"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Relationship Between the Cosmos and the Individual`, ja: `Relationship Between the Cosmos and the Individual` } },
      { type: "paragraph", text: { en: `Jyotish Astrology reveals the relationship between the cosmic totality and individual reality. The complete system of sidereal astrology was cognized by the ancient sage Maharishi Parashara, who is said to have revealed the mathematical and astronomical principles used to forecast future trends and prescribe remedial measures designed to minimise potential difficulties.`, ja: `Jyotish Astrology reveals the relationship between the cosmic totality and individual reality. The complete system of sidereal astrology was cognized by the ancient sage Maharishi Parashara, who is said to have revealed the mathematical and astronomical principles used to forecast future trends and prescribe remedial measures designed to minimise potential difficulties.` } },
      { type: "paragraph", text: { en: `According to this understanding, the cosmos is an intelligently organised and deeply interconnected whole. Events do not occur in isolation; rather, one event naturally leads to another through an ongoing process of unfoldment.`, ja: `According to this understanding, the cosmos is an intelligently organised and deeply interconnected whole. Events do not occur in isolation; rather, one event naturally leads to another through an ongoing process of unfoldment.` } },
      { type: "paragraph", text: { en: `From this perspective, the future can be understood by interpreting the code contained within the planetary arrangements present at the time of birth. Through this cosmic blueprint, Jyotish seeks to reveal the relationship between individual experience and the greater intelligence that governs the universe.`, ja: `From this perspective, the future can be understood by interpreting the code contained within the planetary arrangements present at the time of birth. Through this cosmic blueprint, Jyotish seeks to reveal the relationship between individual experience and the greater intelligence that governs the universe.` } },
    ],
  },
  {
    id: "planetary-antidotes",
    section: "remedies",
    title: { en: `Planetary Antidotes in Jyotish`, ja: `Planetary Antidotes in Jyotish` },
    related: ["gemstones","mantras","preventive-capabilities"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Planetary Antidotes in Jyotish`, ja: `Planetary Antidotes in Jyotish` } },
      { type: "paragraph", text: { en: `Summary: This article explores Remedial Measures or Planetary Antidotes (Upaye or Upayes) in Jyotish. It includes a detailed discussion of wearing gemstones associated with specific planets, chanting planetary mantras, performing charitable acts, and conducting Vedic rituals to harmonise planetary energies.`, ja: `Summary: This article explores Remedial Measures or Planetary Antidotes (Upaye or Upayes) in Jyotish. It includes a detailed discussion of wearing gemstones associated with specific planets, chanting planetary mantras, performing charitable acts, and conducting Vedic rituals to harmonise planetary energies.` } },
      { type: "heading", level: 3, text: { en: `Planetary Antidotes (Upaye) – Remedial Measures in Jyotish`, ja: `Planetary Antidotes (Upaye) – Remedial Measures in Jyotish` } },
      { type: "paragraph", text: { en: `Vedic Astrology is fundamentally karmic in nature. It predicts both the type and duration of positive and negative returning karma, helping us understand what experiences are likely to arise in different areas of life and, perhaps most importantly, when they are likely to occur.`, ja: `Vedic Astrology is fundamentally karmic in nature. It predicts both the type and duration of positive and negative returning karma, helping us understand what experiences are likely to arise in different areas of life and, perhaps most importantly, when they are likely to occur.` } },
      { type: "paragraph", text: { en: `One of the great strengths of Jyotish is that it comes from a tradition which teaches that suffering is not inevitable. It is therefore no surprise that Jyotish provides a range of practical techniques designed to deflect, minimise, or greatly reduce the effects of returning negative karma. These methods are commonly known as remedial measures or planetary antidotes (Upaye or Upayes).`, ja: `One of the great strengths of Jyotish is that it comes from a tradition which teaches that suffering is not inevitable. It is therefore no surprise that Jyotish provides a range of practical techniques designed to deflect, minimise, or greatly reduce the effects of returning negative karma. These methods are commonly known as remedial measures or planetary antidotes (Upaye or Upayes).` } },
      { type: "paragraph", text: { en: `A Vedic Astrologer can identify imbalances within an individual's birth chart by interpreting the code represented by the planetary positions at birth. Based on this analysis, practical recommendations can be given to help "avert the danger that has not yet arisen." While these remedies may not completely eliminate karma, they can certainly modify its effects and lessen its impact.`, ja: `A Vedic Astrologer can identify imbalances within an individual's birth chart by interpreting the code represented by the planetary positions at birth. Based on this analysis, practical recommendations can be given to help "avert the danger that has not yet arisen." While these remedies may not completely eliminate karma, they can certainly modify its effects and lessen its impact.` } },
      { type: "paragraph", text: { en: `Planetary remedies are intended to balance negative planetary influences and restore greater harmony and equilibrium in life. They can also strengthen positive planetary influences, thereby maximising favourable returning karmas.`, ja: `Planetary remedies are intended to balance negative planetary influences and restore greater harmony and equilibrium in life. They can also strengthen positive planetary influences, thereby maximising favourable returning karmas.` } },
      { type: "paragraph", text: { en: `The remedial measures prescribed in Jyotish generally fall into four main categories:`, ja: `The remedial measures prescribed in Jyotish generally fall into four main categories:` } },
      { type: "paragraph", text: { en: `• Wearing gemstones associated with a particular planet`, ja: `• Wearing gemstones associated with a particular planet` } },
      { type: "paragraph", text: { en: `• Chanting planetary-related mantras`, ja: `• Chanting planetary-related mantras` } },
      { type: "paragraph", text: { en: `• Performing specific acts of charity`, ja: `• Performing specific acts of charity` } },
      { type: "paragraph", text: { en: `• Conducting Vedic rituals to balance planetary energies`, ja: `• Conducting Vedic rituals to balance planetary energies` } },
      { type: "paragraph", text: { en: `These remedies are not based on superstition. They have survived the test of time through countless generations. Their effectiveness is rooted in the Vedic understanding that everything in the universe is interconnected. This Vedic Model of Reality is increasingly finding support from modern scientific perspectives and is also reflected in the Vedic and Buddhist concept of Indra's Net [1].`, ja: `These remedies are not based on superstition. They have survived the test of time through countless generations. Their effectiveness is rooted in the Vedic understanding that everything in the universe is interconnected. This Vedic Model of Reality is increasingly finding support from modern scientific perspectives and is also reflected in the Vedic and Buddhist concept of Indra's Net [1].` } },
      { type: "paragraph", text: { en: `There is a famous lyric from a song by Joni Mitchell released in 1970: "We are stardust, we are golden." From the perspective of modern astrophysics, this is remarkably true. Nearly all the elements that make up the human body, apart from hydrogen, were forged in the interiors of stars billions of years ago. We therefore have a genuine connection with the stars because much of the material from which we are made originated there. Many people report that wearing a high-quality Jyotish gemstone reminds them of this connection at a very deep level.`, ja: `There is a famous lyric from a song by Joni Mitchell released in 1970: "We are stardust, we are golden." From the perspective of modern astrophysics, this is remarkably true. Nearly all the elements that make up the human body, apart from hydrogen, were forged in the interiors of stars billions of years ago. We therefore have a genuine connection with the stars because much of the material from which we are made originated there. Many people report that wearing a high-quality Jyotish gemstone reminds them of this connection at a very deep level.` } },
      { type: "paragraph", text: { en: `Although not specifically discussed in the classical Jyotish texts, many astrologers also agree that spiritual practices can significantly modify returning karma. In particular, mantra-based Vedic meditation techniques appear to have a profound effect. When astrologers examined the birth charts of long-term meditators, they often found that their actual life experiences were considerably more favourable than the charts alone might have suggested.`, ja: `Although not specifically discussed in the classical Jyotish texts, many astrologers also agree that spiritual practices can significantly modify returning karma. In particular, mantra-based Vedic meditation techniques appear to have a profound effect. When astrologers examined the birth charts of long-term meditators, they often found that their actual life experiences were considerably more favourable than the charts alone might have suggested.` } },
      { type: "paragraph", text: { en: `For those fortunate enough to have a personal Guru, the Grace of the Guru can remove major obstacles from life. Such individuals should consider themselves especially blessed.`, ja: `For those fortunate enough to have a personal Guru, the Grace of the Guru can remove major obstacles from life. Such individuals should consider themselves especially blessed.` } },
    ],
  },
  {
    id: "gemstones",
    section: "remedies",
    title: { en: `Wearing Gemstones as Planetary Antidotes`, ja: `Wearing Gemstones as Planetary Antidotes` },
    related: ["planetary-antidotes","mantras","natural-benefics-malefics"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Wearing Gemstones as Planetary Antidotes`, ja: `Wearing Gemstones as Planetary Antidotes` } },
      { type: "paragraph", text: { en: `In Vedic Astrology, every planet is associated with a specific gemstone. For example, the Sun corresponds to ruby, Venus to diamond, and Saturn to blue sapphire. When an auspicious planet in the birth chart requires strengthening—and in Jyotish a stronger auspicious planet is generally beneficial—wearing the gemstone associated with that planet can help amplify its positive influence.`, ja: `In Vedic Astrology, every planet is associated with a specific gemstone. For example, the Sun corresponds to ruby, Venus to diamond, and Saturn to blue sapphire. When an auspicious planet in the birth chart requires strengthening—and in Jyotish a stronger auspicious planet is generally beneficial—wearing the gemstone associated with that planet can help amplify its positive influence.` } },
      { type: "paragraph", text: { en: `The key word here is auspicious. Only auspicious planets should be strengthened through gemstones. In this context, auspicious means a functional benefic. If a planet is not auspicious for a particular Ascendant, alternative remedial measures, such as mantras, are generally recommended instead.`, ja: `The key word here is auspicious. Only auspicious planets should be strengthened through gemstones. In this context, auspicious means a functional benefic. If a planet is not auspicious for a particular Ascendant, alternative remedial measures, such as mantras, are generally recommended instead.` } },
      { type: "paragraph", text: { en: `Unfortunately, some modern Jyotish books fail to explain this important distinction clearly, which can lead to serious misunderstandings.`, ja: `Unfortunately, some modern Jyotish books fail to explain this important distinction clearly, which can lead to serious misunderstandings.` } },
      { type: "paragraph", text: { en: `Because many planets rule two houses simultaneously, determining whether a planet is favourable or unfavourable for a particular Ascendant can become quite complex. As the Ascendant changes within the Sidereal Zodiac, the functional benefic or functional malefic nature of a planet also changes.`, ja: `Because many planets rule two houses simultaneously, determining whether a planet is favourable or unfavourable for a particular Ascendant can become quite complex. As the Ascendant changes within the Sidereal Zodiac, the functional benefic or functional malefic nature of a planet also changes.` } },
      { type: "paragraph", text: { en: `This topic is discussed in greater detail elsewhere, but as a broad guideline—and Jyotish always has exceptions—any planet ruling the first, fifth, or ninth house is generally considered auspicious regardless of any secondary house ownership.`, ja: `This topic is discussed in greater detail elsewhere, but as a broad guideline—and Jyotish always has exceptions—any planet ruling the first, fifth, or ninth house is generally considered auspicious regardless of any secondary house ownership.` } },
      { type: "heading", level: 3, text: { en: `Planet and Gemstone Associations in Jyotish`, ja: `Planet and Gemstone Associations in Jyotish` } },
      { type: "paragraph", text: { en: `The traditional gemstone associations for the nine planets are as follows:`, ja: `The traditional gemstone associations for the nine planets are as follows:` } },
      { type: "paragraph", text: { en: `• Sun – Ruby`, ja: `• Sun – Ruby` } },
      { type: "paragraph", text: { en: `• Moon – Pearl`, ja: `• Moon – Pearl` } },
      { type: "paragraph", text: { en: `• Mars – Red Coral`, ja: `• Mars – Red Coral` } },
      { type: "paragraph", text: { en: `• Mercury – Emerald`, ja: `• Mercury – Emerald` } },
      { type: "paragraph", text: { en: `• Jupiter – Yellow Sapphire`, ja: `• Jupiter – Yellow Sapphire` } },
      { type: "paragraph", text: { en: `• Venus – Diamond`, ja: `• Venus – Diamond` } },
      { type: "paragraph", text: { en: `• Saturn – Blue Sapphire`, ja: `• Saturn – Blue Sapphire` } },
      { type: "paragraph", text: { en: `• Rahu – Gomed (Hessonite Garnet)`, ja: `• Rahu – Gomed (Hessonite Garnet)` } },
      { type: "paragraph", text: { en: `• Ketu – Cat's Eye (Chrysoberyl)`, ja: `• Ketu – Cat's Eye (Chrysoberyl)` } },
      { type: "paragraph", text: { en: `Note: Gomed is also known as Hessonite Garnet, while Cat's Eye generally refers to Chrysoberyl.`, ja: `Note: Gomed is also known as Hessonite Garnet, while Cat's Eye generally refers to Chrysoberyl.` } },
      { type: "paragraph", text: { en: `Jyotish is also very specific regarding the weight and quality of gemstones, the metal in which they should be set, and even the finger on which they should be worn [2]. For remedial purposes, gemstones should ideally be natural rather than synthetic or laboratory-created [3].`, ja: `Jyotish is also very specific regarding the weight and quality of gemstones, the metal in which they should be set, and even the finger on which they should be worn [2]. For remedial purposes, gemstones should ideally be natural rather than synthetic or laboratory-created [3].` } },
      { type: "paragraph", text: { en: `To be effective, gemstones should remain in contact with the skin. This is typically achieved through specially designed ring settings or by wearing the stone as a pendant.`, ja: `To be effective, gemstones should remain in contact with the skin. This is typically achieved through specially designed ring settings or by wearing the stone as a pendant.` } },
      { type: "paragraph", text: { en: `Some Jyotish experts even suggest that the gold itself—provided it is 22-carat quality—may reduce a significant proportion of planetary negativity when worn in a chain or ring. If correct, this is certainly an interesting observation.`, ja: `Some Jyotish experts even suggest that the gold itself—provided it is 22-carat quality—may reduce a significant proportion of planetary negativity when worn in a chain or ring. If correct, this is certainly an interesting observation.` } },
      { type: "paragraph", text: { en: `Compared with Western Astrology, the use of gemstones in Jyotish is far more personalised. Western systems typically assign a birthstone based upon an individual's Sun sign, whereas Vedic Astrology recommends gemstones based upon a detailed analysis of the entire birth chart.`, ja: `Compared with Western Astrology, the use of gemstones in Jyotish is far more personalised. Western systems typically assign a birthstone based upon an individual's Sun sign, whereas Vedic Astrology recommends gemstones based upon a detailed analysis of the entire birth chart.` } },
      { type: "heading", level: 3, text: { en: `Semi-Precious Gemstone Equivalents`, ja: `Semi-Precious Gemstone Equivalents` } },
      { type: "paragraph", text: { en: `If a high-quality precious gemstone is beyond our budget, certain semi-precious alternatives may be used. However, the general understanding is that they do not offer the same level of benefit or protection as the traditional precious stones.`, ja: `If a high-quality precious gemstone is beyond our budget, certain semi-precious alternatives may be used. However, the general understanding is that they do not offer the same level of benefit or protection as the traditional precious stones.` } },
      { type: "paragraph", text: { en: `In India, the following alternatives are commonly used:`, ja: `In India, the following alternatives are commonly used:` } },
      { type: "paragraph", text: { en: `• Red Spinel for the Sun`, ja: `• Red Spinel for the Sun` } },
      { type: "paragraph", text: { en: `• Green Tourmaline for Mercury`, ja: `• Green Tourmaline for Mercury` } },
      { type: "paragraph", text: { en: `• Yellow Topaz (preferred) or Yellow Citrine for Jupiter`, ja: `• Yellow Topaz (preferred) or Yellow Citrine for Jupiter` } },
      { type: "paragraph", text: { en: `• White Sapphire or Phenakite for Venus`, ja: `• White Sapphire or Phenakite for Venus` } },
      { type: "paragraph", text: { en: `• Blue Spinel for Saturn`, ja: `• Blue Spinel for Saturn` } },
      { type: "heading", level: 3, text: { en: `Wearing Gemstones Based on our Ascendant`, ja: `Wearing Gemstones Based on our Ascendant` } },
      { type: "paragraph", text: { en: `If we know our Ascendant, or rising sign in the Sidereal Zodiac, we can safely wear the gemstone associated with the planet ruling that sign. This is considered a universally beneficial remedy and is something almost everyone can do to receive positive results.`, ja: `If we know our Ascendant, or rising sign in the Sidereal Zodiac, we can safely wear the gemstone associated with the planet ruling that sign. This is considered a universally beneficial remedy and is something almost everyone can do to receive positive results.` } },
      { type: "paragraph", text: { en: `By strengthening the Ascendant Lord—the planet ruling the Ascendant—we also strengthen the overall chart. This can provide some assistance in mitigating difficulties shown elsewhere in the horoscope, although not to the same extent as remedies specifically targeted toward individual planetary issues.`, ja: `By strengthening the Ascendant Lord—the planet ruling the Ascendant—we also strengthen the overall chart. This can provide some assistance in mitigating difficulties shown elsewhere in the horoscope, although not to the same extent as remedies specifically targeted toward individual planetary issues.` } },
      { type: "paragraph", text: { en: `Strengthening the Ascendant Lord generally produces positive effects. Some astrologers note a possible exception for Scorpio Ascendants because Mars rules both the first and sixth houses.`, ja: `Strengthening the Ascendant Lord generally produces positive effects. Some astrologers note a possible exception for Scorpio Ascendants because Mars rules both the first and sixth houses.` } },
      { type: "paragraph", text: { en: `If we already possess a Western-style birth chart based on the Tropical Zodiac, conversion to the Sidereal Zodiac can be achieved by subtracting the relevant Ayanamsha for the birth date [4]. Once this is done, the appropriate gemstone can be selected.`, ja: `If we already possess a Western-style birth chart based on the Tropical Zodiac, conversion to the Sidereal Zodiac can be achieved by subtracting the relevant Ayanamsha for the birth date [4]. Once this is done, the appropriate gemstone can be selected.` } },
      { type: "paragraph", text: { en: `Alternatively, various online tools based upon the Sidereal Zodiac can provide gemstone recommendations. Accurate birth times are essential for reliable results. If uncertainty exists regarding birth time, it is wise to compare multiple reports or consult an experienced Vedic Astrologer.`, ja: `Alternatively, various online tools based upon the Sidereal Zodiac can provide gemstone recommendations. Accurate birth times are essential for reliable results. If uncertainty exists regarding birth time, it is wise to compare multiple reports or consult an experienced Vedic Astrologer.` } },
    ],
  },
  {
    id: "mantras",
    section: "remedies",
    title: { en: `Chanting Planetary Related Mantras to Remove Negative Karma`, ja: `Chanting Planetary Related Mantras to Remove Negative Karma` },
    related: ["gemstones","vedic-rituals","charity"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Chanting Planetary Related Mantras to Remove Negative Karma`, ja: `Chanting Planetary Related Mantras to Remove Negative Karma` } },
      { type: "paragraph", text: { en: `While gemstones can strengthen auspicious planets, wearing the gemstone associated with a functional malefic planet may actually increase difficulties. In such cases, chanting planetary mantras is often the preferred remedy.`, ja: `While gemstones can strengthen auspicious planets, wearing the gemstone associated with a functional malefic planet may actually increase difficulties. In such cases, chanting planetary mantras is often the preferred remedy.` } },
      { type: "paragraph", text: { en: `Mantras are traditionally recited in Sanskrit and are said to "upwardly manage" the forces of nature, or Devas. Specific mantras can be used to harmonise negative planetary influences. In a sense, mantras act like passwords that connect us to higher levels of consciousness and facilitate transcendence.`, ja: `Mantras are traditionally recited in Sanskrit and are said to "upwardly manage" the forces of nature, or Devas. Specific mantras can be used to harmonise negative planetary influences. In a sense, mantras act like passwords that connect us to higher levels of consciousness and facilitate transcendence.` } },
      { type: "paragraph", text: { en: `A Jyotish Astrologer can identify problematic planets in a birth chart and recommend suitable mantras to reduce their negative effects.`, ja: `A Jyotish Astrologer can identify problematic planets in a birth chart and recommend suitable mantras to reduce their negative effects.` } },
      { type: "paragraph", text: { en: `At their simplest, planetary mantras generally follow the pattern:`, ja: `At their simplest, planetary mantras generally follow the pattern:` } },
      { type: "paragraph", text: { en: `"Om – [Planet's Sanskrit Name] – Namaha"`, ja: `"Om – [Planet's Sanskrit Name] – Namaha"` } },
      { type: "paragraph", text: { en: `These are commonly repeated 108 times daily using a mala or rosary. The number 108 is derived from the nine planets multiplied by the twelve zodiac signs (9 × 12 = 108).`, ja: `These are commonly repeated 108 times daily using a mala or rosary. The number 108 is derived from the nine planets multiplied by the twelve zodiac signs (9 × 12 = 108).` } },
      { type: "paragraph", text: { en: `For example, the mantra for Venus is:`, ja: `For example, the mantra for Venus is:` } },
      { type: "paragraph", text: { en: `"Om Shukraya Namaha"`, ja: `"Om Shukraya Namaha"` } },
      { type: "heading", level: 3, text: { en: `Basic Planetary Mantras to Chant`, ja: `Basic Planetary Mantras to Chant` } },
      { type: "paragraph", text: { en: `• Sun: Om Suryaya Namaha`, ja: `• Sun: Om Suryaya Namaha` } },
      { type: "paragraph", text: { en: `• Moon: Om Somaya Namaha`, ja: `• Moon: Om Somaya Namaha` } },
      { type: "paragraph", text: { en: `• Mars: Om Mangalaya Namaha`, ja: `• Mars: Om Mangalaya Namaha` } },
      { type: "paragraph", text: { en: `• Mercury: Om Budhaya Namaha`, ja: `• Mercury: Om Budhaya Namaha` } },
      { type: "paragraph", text: { en: `• Jupiter: Om Brihaspataye Namaha`, ja: `• Jupiter: Om Brihaspataye Namaha` } },
      { type: "paragraph", text: { en: `• Venus: Om Shukraya Namaha`, ja: `• Venus: Om Shukraya Namaha` } },
      { type: "paragraph", text: { en: `• Saturn: Om Shanaye Namaha`, ja: `• Saturn: Om Shanaye Namaha` } },
      { type: "paragraph", text: { en: `• Rahu: Om Rahave Namaha`, ja: `• Rahu: Om Rahave Namaha` } },
      { type: "paragraph", text: { en: `• Ketu: Om Ketave Namaha`, ja: `• Ketu: Om Ketave Namaha` } },
      { type: "paragraph", text: { en: `Because correct pronunciation is important, it is advisable to learn from a reputable source.`, ja: `Because correct pronunciation is important, it is advisable to learn from a reputable source.` } },
      { type: "paragraph", text: { en: `A Jyotish Astrologer may further refine the remedy by identifying the periods during which a planet's influence is strongest—particularly during its Maha Dasha—and recommending chanting during that specific timeframe.`, ja: `A Jyotish Astrologer may further refine the remedy by identifying the periods during which a planet's influence is strongest—particularly during its Maha Dasha—and recommending chanting during that specific timeframe.` } },
      { type: "heading", level: 3, text: { en: `Mantra for Harmony Between the Nine Planets`, ja: `Mantra for Harmony Between the Nine Planets` } },
      { type: "paragraph", text: { en: `Another option is the powerful Nav Graha mantra, which seeks to harmonise the energies of all nine planets simultaneously:`, ja: `Another option is the powerful Nav Graha mantra, which seeks to harmonise the energies of all nine planets simultaneously:` } },
      { type: "paragraph", text: { en: `adityaaya cha somaaya mangalaaya budhaaya cha |`, ja: `adityaaya cha somaaya mangalaaya budhaaya cha |` } },
      { type: "paragraph", text: { en: `guru shukra shanibhyash cha raahave ketave namaha ||`, ja: `guru shukra shanibhyash cha raahave ketave namaha ||` } },
      { type: "paragraph", text: { en: `This mantra is relatively easy to learn through regular repetition.`, ja: `This mantra is relatively easy to learn through regular repetition.` } },
      { type: "heading", level: 3, text: { en: `General Mantras for Removing Negativity and Suffering`, ja: `General Mantras for Removing Negativity and Suffering` } },
      { type: "paragraph", text: { en: `A widely recommended mantra is:`, ja: `A widely recommended mantra is:` } },
      { type: "paragraph", text: { en: `"Auṁ Namaḥ Śivāya" (Om Namah Shivaya)`, ja: `"Auṁ Namaḥ Śivāya" (Om Namah Shivaya)` } },
      { type: "paragraph", text: { en: `This simple yet powerful mantra is traditionally believed to remove negativity and suffering.`, ja: `This simple yet powerful mantra is traditionally believed to remove negativity and suffering.` } },
      { type: "paragraph", text: { en: `An even more powerful option is the Maha Mrityunjaya Mantra, although it requires greater effort to learn correctly.`, ja: `An even more powerful option is the Maha Mrityunjaya Mantra, although it requires greater effort to learn correctly.` } },
      { type: "paragraph", text: { en: `Why are these mantras considered so effective? It is often said that "Shiva sits above all the planets" [5]. In essence, this means that Shiva Tattva—Shiva Consciousness—has the power to transcend and override the planetary influences shown in a birth chart. Chanting Shiva mantras helps enliven this higher consciousness within our awareness [6].`, ja: `Why are these mantras considered so effective? It is often said that "Shiva sits above all the planets" [5]. In essence, this means that Shiva Tattva—Shiva Consciousness—has the power to transcend and override the planetary influences shown in a birth chart. Chanting Shiva mantras helps enliven this higher consciousness within our awareness [6].` } },
    ],
  },
  {
    id: "charity",
    section: "remedies",
    title: { en: `Acts of Charity to Balance Planetary Energies`, ja: `Acts of Charity to Balance Planetary Energies` },
    related: ["planetary-antidotes","vedic-rituals","jyotish-and-karma"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Acts of Charity to Balance Planetary Energies`, ja: `Acts of Charity to Balance Planetary Energies` } },
      { type: "paragraph", text: { en: `Because the Vedic tradition sees all existence as interconnected, specific acts of charity are believed to reduce karmas associated with particular planets.`, ja: `Because the Vedic tradition sees all existence as interconnected, specific acts of charity are believed to reduce karmas associated with particular planets.` } },
      { type: "paragraph", text: { en: `Even if one views these ideas symbolically, giving a portion of one's income to worthwhile causes remains beneficial. A living enlightened Vedic Saint encourages everyone to donate a small percentage of their income, explaining that doing so may reduce the likelihood of disputes, legal difficulties, and related challenges.`, ja: `Even if one views these ideas symbolically, giving a portion of one's income to worthwhile causes remains beneficial. A living enlightened Vedic Saint encourages everyone to donate a small percentage of their income, explaining that doing so may reduce the likelihood of disputes, legal difficulties, and related challenges.` } },
      { type: "paragraph", text: { en: `Some remedies are surprisingly simple. For example, feeding crows on a Saturday is traditionally believed to alleviate certain karmic burdens connected with Saturn.`, ja: `Some remedies are surprisingly simple. For example, feeding crows on a Saturday is traditionally believed to alleviate certain karmic burdens connected with Saturn.` } },
      { type: "paragraph", text: { en: `Since different planets are linked to specific days of the week, charitable acts are often performed on the day associated with the relevant planet.`, ja: `Since different planets are linked to specific days of the week, charitable acts are often performed on the day associated with the relevant planet.` } },
      { type: "paragraph", text: { en: `Although some may regard these practices as superstitious, they have endured across generations. Modern scientific interest in interconnected systems provides additional support for concepts long recognised by the ancient Vedic sages.`, ja: `Although some may regard these practices as superstitious, they have endured across generations. Modern scientific interest in interconnected systems provides additional support for concepts long recognised by the ancient Vedic sages.` } },
    ],
  },
  {
    id: "vedic-rituals",
    section: "remedies",
    title: { en: `Conducting Vedic Rituals to Remove Negativity`, ja: `Conducting Vedic Rituals to Remove Negativity` },
    related: ["mantras","charity","planetary-antidotes"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Conducting Vedic Rituals to Remove Negativity`, ja: `Conducting Vedic Rituals to Remove Negativity` } },
      { type: "paragraph", text: { en: `Since ancient times, Vedic rituals have been used to harmonise and manage the forces of nature. Traditional ceremonies known as Yagnas, Yajnas, or Yagyas were believed to bring timely rainfall, healthy crops, and prosperity.`, ja: `Since ancient times, Vedic rituals have been used to harmonise and manage the forces of nature. Traditional ceremonies known as Yagnas, Yajnas, or Yagyas were believed to bring timely rainfall, healthy crops, and prosperity.` } },
      { type: "paragraph", text: { en: `In a similar way, difficulties caused by imbalanced planetary energies in a birth chart can be addressed through these sacred rituals.`, ja: `In a similar way, difficulties caused by imbalanced planetary energies in a birth chart can be addressed through these sacred rituals.` } },
      { type: "paragraph", text: { en: `Some may interpret these ceremonies as "planet worship," but their purpose is much more subtle and profound. They may be better understood as a form of karmic engineering designed to modify returning karmas and reduce suffering.`, ja: `Some may interpret these ceremonies as "planet worship," but their purpose is much more subtle and profound. They may be better understood as a form of karmic engineering designed to modify returning karmas and reduce suffering.` } },
      { type: "paragraph", text: { en: `The procedures for conducting these rituals were traditionally regarded as Divine knowledge given for the benefit of humanity.`, ja: `The procedures for conducting these rituals were traditionally regarded as Divine knowledge given for the benefit of humanity.` } },
      { type: "paragraph", text: { en: `When performed correctly, with the appropriate Vedic mantras and procedures, these ceremonies bring Graha Shanti—peace from the planets. They are ideally performed by highly trained pundits with elevated levels of consciousness.`, ja: `When performed correctly, with the appropriate Vedic mantras and procedures, these ceremonies bring Graha Shanti—peace from the planets. They are ideally performed by highly trained pundits with elevated levels of consciousness.` } },
      { type: "paragraph", text: { en: `Their effectiveness is generally considered greatest when conducted in an Ashram or Temple according to traditional guidelines and with all required ingredients. They may be especially powerful when performed under the guidance of an enlightened Guru.`, ja: `Their effectiveness is generally considered greatest when conducted in an Ashram or Temple according to traditional guidelines and with all required ingredients. They may be especially powerful when performed under the guidance of an enlightened Guru.` } },
      { type: "paragraph", text: { en: `These rituals can target the effects of a single problematic planet or, when necessary, address all nine planetary energies simultaneously to create balance, harmony, and peace throughout the chart.`, ja: `These rituals can target the effects of a single problematic planet or, when necessary, address all nine planetary energies simultaneously to create balance, harmony, and peace throughout the chart.` } },
      { type: "heading", level: 3, text: { en: `Footnotes`, ja: `Footnotes` } },
    ],
  }
];
